const updates = $json.result || [];
if (updates.length === 0) {
  return [];
}

const items = [];

for (const u of updates) {
  // 1. Gestione Callback Query (Click su pulsante 'Segna come completato')
  if (u.callback_query && String(u.callback_query.from.id) === String($env.TELEGRAM_USER_ID)) {
    const cb = u.callback_query;
    const data = cb.data || '';
    if (data.startsWith('done:')) {
      const pageId = data.replace('done:', '');
      items.push({
        json: {
          update_id: u.update_id,
          is_callback: true,
          mode: 'callback_done',
          callback_query_id: cb.id,
          chat_id: cb.message?.chat?.id || Number($env.TELEGRAM_USER_ID),
          message_id: cb.message?.message_id,
          original_text: cb.message?.text || '',
          page_id: pageId,
          date: new Date().toISOString()
        }
      });
    }
    continue;
  }

  // 2. Gestione Messaggi di testo o vocali
  if (u.message && String(u.message.from.id) === String($env.TELEGRAM_USER_ID)) {
    const msg = u.message;
    const rawText = (msg.text || msg.caption || '').trim();
    const cleanText = rawText.replace(/^[\"'*`«»\s]+|[\"'*`«»\s]+$/g, '').trim();
    const isVoice = Boolean(msg.voice || msg.audio);

    if (isVoice) {
      items.push({
        json: {
          update_id: u.update_id,
          is_callback: false,
          mode: 'capture_voice',
          chat_id: msg.chat.id,
          message_id: msg.message_id,
          text: cleanText,
          raw_text: rawText,
          date: new Date(msg.date * 1000).toISOString()
        }
      });
      continue;
    }

    const todayIso = new Date().toISOString().slice(0, 10);
    const optionsDate = { timeZone: 'Europe/Rome', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const todayFormatted = new Date().toLocaleDateString('it-IT', optionsDate);

    const gemini_prompt = `Sei il router semantico del Second Brain di Angelo.
CONTESTO ATTUALE:
- Data odierna di riferimento: ${todayFormatted} (${todayIso})
- Fuso orario: Europe/Rome

Analizza il messaggio dell'utente ed estrai le intenzioni e i parametri in un JSON valido.

Possibili intenti:
- TASK_ACTION: L'utente vuole completare, annullare, cancellare, chiudere, o impostare/aggiornare la scadenza (deadline) di task esistenti su Notion.
  * Esempi: "completa 1", "fatto task 2", "cancella task redes", "segna le task di sistemi operativi come cancelled", "imposta a queste attività la deadline per il 20 ottobre 1. Sostituire... 2. Gestire...", "sposta la scadenza a venerdì".
- ADD_CALENDAR: L'utente vuole aggiungere o fissare un evento, impegno, lezione, riunione o promemoria su Google Calendar (es: "aggiungi evento domani alle 10", "ricordami di...").
- QUERY_AGENT: L'utente fa domande sul proprio programma, agenda, impegni di oggi/domani, orari, task aperti o risorse (es: "cosa ho da fare oggi?", "mostrami le task", "trovami le note").
- CAPTURE_NOTE: L'utente scrive una nuova nota, appunto, idea, link o un nuovo task da creare da zero (es: "comprare il latte", "idea: nuovo sito").

Formato JSON atteso:
{
  "intent": "TASK_ACTION" | "ADD_CALENDAR" | "QUERY_AGENT" | "CAPTURE_NOTE",
  "action": "COMPLETE" | "CANCEL" | "SET_DEADLINE" | "UPDATE_STATUS" | "UPDATE_BOTH" | null,
  "due_date": "YYYY-MM-DD" | null,
  "target_status": "Done" | "Cancelled" | "In progress" | null,
  "target_titles": ["titolo o porzione di titolo task 1", "titolo task 2", ...] | [],
  "target_indices": [1, 2, ...] | []
}

Nota per target_status: impostalo SOLO se l'utente ha chiesto esplicitamente di cambiare stato (es. fatto, completato, cancellato, annullato). Se chiede SOLO di impostare o spostare la scadenza/deadline, target_status DEVE essere null.

Messaggio utente:
\"${cleanText}\"`;

    items.push({
      json: {
        update_id: u.update_id,
        is_callback: false,
        gemini_prompt,
        chat_id: msg.chat.id,
        message_id: msg.message_id,
        clean_text: cleanText,
        raw_text: rawText,
        date: new Date(msg.date * 1000).toISOString()
      }
    });
  }
}

return items;

const query = ($('Apply Semantic Intent').first() ? $('Apply Semantic Intent') : $('Filter Security & Prepare Updates')).item.json.text;
const tasksRaw = $('Query Active Tasks').first().json.results || [];
const resRaw = $('Query Recent Resources').first().json.results || [];

// 1. Estrazione Eventi Google Calendar
let calRaw = [];
try {
  calRaw = $('Get Calendar Events for Agenda').all() || [];
} catch (e) {
  calRaw = [];
}

const calendarEvents = [];
for (const e of calRaw) {
  const j = e.json || {};
  if (!j.summary) continue;
  calendarEvents.push({
    titolo: j.summary,
    inizio: j.start?.dateTime || j.start?.date || 'N/A',
    fine: j.end?.dateTime || j.end?.date || 'N/A',
    luogo: j.location || '',
    note: (j.description || '').slice(0, 150)
  });
}

// 2. Estrazione Task Notion
const tasks = tasksRaw.map((t, idx) => ({
  numero: idx + 1,
  id: t.id,
  nome: t.properties['Task Name']?.title[0]?.plain_text || 'Senza nome',
  scadenza: t.properties['Due Date']?.date?.start || 'Nessuna',
  priorita: t.properties['Priority']?.select?.name || 'P3 - Normal',
  stato: t.properties['Status']?.status?.name || 'To Do'
}));

// 3. Estrazione Risorse Notion
const resources = resRaw.map(r => ({
  titolo: r.properties['Title']?.title[0]?.plain_text || 'Senza titolo',
  url: r.properties['URL']?.url || '',
  tipo: r.properties['Type']?.select?.name || 'Risorsa',
  summary: r.properties['Summary / Notes']?.rich_text[0]?.plain_text || ''
}));

// 4. Costruzione Inline Keyboard per completamento rapido dei task
const inline_keyboard = [];
if (tasksRaw.length > 0) {
  for (let i = 0; i < Math.min(tasksRaw.length, 5); i++) {
    const t = tasksRaw[i];
    const pageId = t.id.replace(/-/g, '');
    const title = t.properties['Task Name']?.title[0]?.plain_text || `Task ${i + 1}`;
    inline_keyboard.push([
      {
        text: `✅ ${i + 1}. Segna come fatto: ${title.slice(0, 26)}`,
        callback_data: `done:${pageId}`
      }
    ]);
  }
}

const todayDateStr = new Date().toLocaleDateString('it-IT', { 
