let item = {};
try {
  item = $('Apply Semantic Intent').item.json;
} catch (e) {
  item = $json;
}

const rawText = (item.raw_text || item.text || '').trim();
const tasksRaw = $json.results || [];

const action = item.action || 'UPDATE_STATUS';
const targetTitles = item.target_titles || [];
const targetIndices = item.target_indices || [];
let targetStatus = item.target_status;
const dueDate = item.due_date;

// Se non è specificata né scadenza né status, deduci se è completamento o annullamento
if (!targetStatus && !dueDate) {
  if (/(cancell|elimin|annull|archiv|rimuov|scart)/i.test(rawText) || /\bcancelled\b/i.test(rawText)) {
    targetStatus = 'Cancelled';
  } else if (/(in corso|in progress)/i.test(rawText)) {
    targetStatus = 'In progress';
  } else {
    targetStatus = 'Done';
  }
}

// 1. Identificazione dei task target
let matchedTasks = [];

// A) Match prioritario tramite titoli / parole chiave (molto più specifico se l'utente ha incollato o menzionato i nomi)
if (targetTitles.length > 0) {
  for (const qTitle of targetTitles) {
    const qLower = qTitle.toLowerCase().trim();
    if (qLower.length < 3) continue;

    // Cerca nei task di Notion
    const found = tasksRaw.find(t => {
      const tName = (t.properties['Task Name']?.title?.[0]?.plain_text || '').toLowerCase();
      // Match per contenimento o stemming
      if (tName.includes(qLower) || qLower.includes(tName)) return true;
      const tokens = qLower.split(/\s+/).filter(w => w.length >= 4);
      return tokens.length > 0 && tokens.every(tok => tName.includes(tok));
    });

    if (found && !matchedTasks.some(m => m.id === found.id)) {
      matchedTasks.push(found);
    }
  }
}

// B) Se nessun titolo ha fatto match, usa gli indici numerici (es: [1, 2, 3])
if (matchedTasks.length === 0 && targetIndices.length > 0) {
  for (const idxNum of targetIndices) {
    const idx = parseInt(idxNum, 10) - 1;
    if (idx >= 0 && idx < tasksRaw.length) {
      const t = tasksRaw[idx];
      if (!matchedTasks.some(m => m.id === t.id)) {
        matchedTasks.push(t);
      }
    }
  }
}

// C) Fallback: se nessun match, controlla parole del rawText
if (matchedTasks.length === 0) {
  let q = rawText.toLowerCase();
  q = q.replace(/\b(segna|metti|imposta|completa|fatto|chiudi|cancella|elimina|annulla|archivia|rimuovi|deadline|scadenza)\b/gi, ' ');
  q = q.replace(/\b(le|la|il|lo|i|gli|del|della|dello|dei|degli|di|da|un|una|uno)\b/gi, ' ');
  q = q.replace(/\b(task|tasks|compit[oi]|attivit[àa]|corso|cosrso|materia)\b/gi, ' ');
  q = q.replace(/[^a-z0-9\s]/gi, ' ').trim();

  const tokens = q.split(/\s+/).filter(w => w.length >= 3);
  if (tokens.length > 0) {
    matchedTasks = tasksRaw.filter(t => {
      const tName = (t.properties['Task Name']?.title?.[0]?.plain_text || '').toLowerCase();
      return tokens.every(tok => {
        const stem = tok.length >= 5 ? tok.slice(0, 5) : tok.length >= 4 ? tok.slice(0, 4) : tok;
        return tName.includes(tok) || tName.includes(stem);
      });
    });
  }
}

if (matchedTasks.length === 0) {
  return [{
    json: {
      found: false,
      chat_id: Number($env.TELEGRAM_USER_ID),
      message: `⚠️ Non ho trovato task corrispondenti tra quelli aperti.\nScrivi *\"Mostrami le task\"* per vedere la lista aggiornata!`
    }
  }];
}

// Costruzione proprietà Notion da aggiornare
const notionProperties = {};
if (targetStatus) {
  notionProperties['Status'] = { status: { name: targetStatus } };
}
if (dueDate) {
  notionProperties['Due Date'] = { date: { start: dueDate } };
}

return matchedTasks.map(t => ({
  json: {
    found: true,
    page_id: t.id,
    task_title: t.properties['Task Name']?.title?.[0]?.plain_text || 'Senza titolo',
    action_type: action,
    target_status: targetStatus,
    due_date: dueDate,
    notion_properties: notionProperties,
    chat_id: Number($env.TELEGRAM_USER_ID)
  }
}));

const item = $json;
const rawText = item.raw_text || item.text;
const now = new Date();

const options = { timeZone: 'Europe/Rome', weekday: 'long', year: 'numeric', month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' };
const currentRef = now.toLocaleString('it-IT', options);
const currentIso = now.toISOString();

const prompt = `Sei un parser specializzato per Google Calendar.
Il tuo compito è estrarre da una richiesta in linguaggio naturale i dati di un evento da inserire in Google Calendar e restituirli ESCLUSIVAMENTE come un oggetto JSON valido.

CONTESTO ATTUALE:
- Data e ora attuale di riferimento: ${currentRef} (${currentIso})
- Fuso orario utente: Europe/Rome (UTC+02:00 / CEST).
- Giorno odierno della settimana: ${now.toLocaleDateString('it-IT', { weekday: 'long', timeZone: 'Europe/Rome' })}.

REGOLE DI ESTRAZIONE:
1. "summary": Titolo chiaro dell'evento. Rimuovi parole superflue come "aggiungi un evento sul calendario", "promemoria per domani", "fissa", virgolette esterne, ecc. Es: "Comprare il caricabatterie".
2. "start": Data e ora di inizio in formato ISO 8601 con offset timezone (es: "2026-10-15T09:00:00+02:00").
   - Se l'utente specifica "tutta la giornata", "tutto il giorno" o non indica un orario specifico, imposta l'inizio alle 09:00:00 del giorno indicato e la fine alle 20:00:00 dello stesso giorno.
   - Se l'utente specifica un orario (es. "alle 15:30" o "dalle 10 alle 12"), imposta l'orario di inizio esatto.
3. "end": Data e ora di fine in formato ISO 8601 con offset timezone.
   - Se non specificato l'orario di fine ma è indicato l'orario di inizio, imposta la fine esattamente 1 ORA DOPO l'inizio.
4. "location": Luogo o aula se menzionato (altrimenti stringa vuota "").
5. "description": Note, dettagli aggiuntivi o promemoria menzionati nel testo (altrimenti stringa vuota "").
6. "colorId": ID colore Google Calendar ("1" lavanda predefinito, "3" viola per IA, "9" blu per Reti, "10" verde per Algoritmi, "5" giallo per Web, "6" arancione per Diseño, "11" rosso fenicottero per cose importanti/urgenti).

RISPONDI ESCLUSIVAMENTE CON IL JSON (senza tag markdown, senza spiegazioni, senza apici).
Formato atteso:
{
  "summary": "...",
  "start": "...",
  "end": "...",
  "location": "...",
  "description": "...",
  "colorId": "1"
}

TESTO UTENTE DA PARSARE:
\"${rawText}\"`;

return {
  json: {
    prompt,
    chat_id: item.chat_id || Number($env.TELEGRAM_USER_ID),
    original_text: rawText
  }
};

const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const clean = raw.replace(/```json\s*/gi, '').replace(/```/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(clean);
} catch (e) {
  const orig = $('Prepare Event Parsing Prompt').item.json.original_text || 'Nuovo Evento';
  parsed = {
    summary: orig,
    start: new Date(Date.now() + 3600000).toISOString(),
    end: new Date(Date.now() + 7200000).toISOString(),
    location: '',
    description: '',
    colorId: '1'
  };
}

if (!parsed.start) {
  parsed.start = new Date(Date.now() + 3600000).toISOString();
}
if (!parsed.end) {
  const s = new Date(parsed.start);
  parsed.end = new Date(s.getTime() + 3600000).toISOString();
}

return {
  json: {
    summary: parsed.summary || 'Evento Calendario',
    start: parsed.start,
    end: parsed.end,
    location: parsed.location || '',
    description: parsed.description || '',
    colorId: String(parsed.colorId || '1'),
    chat_id: Number($env.TELEGRAM_USER_ID)
  }
};

let text = $json.candidates?.[0]?.content?.parts?.[0]?.text || "⚠️ Assistente momentaneamente non disponibile, riprova tra poco.";

// 1. Sostituisci bullet points con asterischi (*   o -   ) con bullet point puliti (• )
text = text.replace(/^(\s*)[*+-]\s+/gm, '$1• ');

// 2. Normalizza bold markdown standard **testo** in *testo* per Telegram legacy Markdown
text = text.replace(/\*\*(.*?)\*\*/g, '*$1*');

// 3. Rimuovi underscore isolati nei testi per evitare entità corsivo errate in Telegram
text = text.replace(/([a-zA-Z0-9])_([a-zA-Z0-9])/g, '$1 $2');

// 4. Bilanciamento asterischi: se il numero di '*' è dispari, rimuovi l'ultimo
const starCount = (text.match(/\*/g) || []).length;
if (starCount % 2 !== 0) {
  const lastIndex = text.lastIndexOf('*');
  text = text.substring(0, lastIndex) + text.substring(lastIndex + 1);
}

// 5. Bilanciamento underscore: se il numero di '_' è dispari, rimuovili
const underCount = (text.match(/_/g) || []).length;
if (underCount % 2 !== 0) {
  text = text.replace(/_/g, '');
}

return {
  json: {
    clean_text: text,
    raw_text: $json.candidates?.[0]?.content?.parts?.[0]?.text || "⚠️ Nessuna risposta generata.",
    chat_id: Number($env.TELEGRAM_USER_ID),
    reply_markup: $('Format Agent Context').first().json.reply_markup || { inline_keyboard: [] }
  }
};

