const created = $json;
let payload = {};
try {
  payload = $('Format Calendar Event Payload').first().json || {};
} catch(e) {}

const summary = created.summary || payload.summary || 'Nuovo Evento';
const startRaw = created.start?.dateTime || created.start?.date || payload.start || '';
const endRaw = created.end?.dateTime || created.end?.date || payload.end || '';
const location = created.location || payload.location || '';
const description = created.description || payload.description || '';

let dateStr = startRaw;
try {
  const d = new Date(startRaw);
  dateStr = d.toLocaleString('it-IT', { timeZone: 'Europe/Rome', weekday: 'short', day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
  if (endRaw) {
    const dEnd = new Date(endRaw);
    const endHours = dEnd.toLocaleTimeString('it-IT', { timeZone: 'Europe/Rome', hour: '2-digit', minute: '2-digit' });
    dateStr += ` ➔ ${endHours}`;
  }
} catch(e) {}

let text = `📅 *Evento Salvato in Google Calendar!* 🎉\n\n` +
  `📌 *Titolo:* ${summary}\n` +
  `⏰ *Quando:* ${dateStr}\n`;

if (location) {
  text += `📍 *Luogo:* ${location}\n`;
}
if (description) {
  text += `📝 *Note:* ${description}\n`;
}
text += `\nL'evento è già attivo e sincronizzato sul tuo Google Calendar! 🚀`;

return {
  json: {
    chat_id: Number($env.TELEGRAM_USER_ID),
    text: text,
    raw_text: `📅 Evento Salvato in Google Calendar! 🎉\n\nTitolo: ${summary}\nQuando: ${dateStr}\n` + (location ? `Luogo: ${location}\n` : '') + `\nL'evento è già sincronizzato sul tuo calendario!`,
    summary: summary
  }
};

const first = $('Resolve Task to Complete').first().json;
const resolveItems = $('Resolve Task to Complete').all();
const titles = resolveItems.map(item => item.json.task_title);

const targetStatus = first.target_status;
const dueDate = first.due_date;

const nl = String.fromCharCode(10);
let text = '';

const count = titles.length;
const isPlural = count > 1;

if (dueDate && targetStatus) {
  text = '✨ *' + (isPlural ? count + ' Task Aggiornati!' : 'Task Aggiornato!') + '*' + nl;
  text += '📅 Nuova scadenza: *' + dueDate + '*' + nl;
  text += '🏷️ Nuovo stato: *' + targetStatus + '*' + nl;
} else if (dueDate) {
  text = '📅 *' + (isPlural ? count + ' Scadenze Aggiornate!' : 'Scadenza Aggiornata!') + '*' + nl;
  text += 'Nuova deadline: *' + dueDate + '*' + nl;
} else if (targetStatus === 'Cancelled') {
  text = '🚫 *' + (isPlural ? count + ' Task Annullati!' : 'Task Annullato!') + '*' + nl;
  text += 'Stato impostato su: *Cancelled*' + nl;
} else if (targetStatus === 'In progress') {
  text = '⏳ *' + (isPlural ? count + ' Task In Corso!' : 'Task In Corso!') + '*' + nl;
  text += 'Stato impostato su: *In progress*' + nl;
} else {
  text = '✅ *' + (isPlural ? count + ' Task Completati!' : 'Task Completato!') + '*' + nl;
  text += 'Segnato come completato su Notion 🎉' + nl;
}

text += titles.map(t => '• *"' + t + '"*').join(nl);

return [{
  json: {
    chat_id: Number($env.TELEGRAM_USER_ID),
    text: text
  }
}];

const prev = $('Filter Security & Prepare Updates').item.json;
let parsed = {};
try {
  let text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  // Pulisci se Gemini restituisce un array invece di oggetto
  const obj = JSON.parse(text);
  parsed = Array.isArray(obj) ? obj[0] : obj;
} catch (e) {
  parsed = { intent: 'CAPTURE_NOTE' };
}

let mode = 'capture_text';
if (parsed.intent === 'TASK_ACTION') {
  mode = 'complete_task_text';
} else if (parsed.intent === 'ADD_CALENDAR') {
  mode = 'add_calendar_event';
} else if (parsed.intent === 'QUERY_AGENT') {
  mode = 'query_agent';
} else {
  mode = 'capture_text';
}

return [{
  json: {
    update_id: prev.update_id,
    mode,
    chat_id: prev.chat_id,
    message_id: prev.message_id,
    text: prev.clean_text,
    raw_text: prev.raw_text,
    action: parsed.action || 'UPDATE_STATUS',
    due_date: parsed.due_date || null,
    target_status: parsed.target_status || null,
    target_titles: parsed.target_titles || [],
    target_indices: parsed.target_indices || [],
    date: prev.date
  }
}];
